def task_func(myString, API_KEY):
    pattern = r'https?://[^\s/$.?#].[^\s]*'
    urls = re.findall(pattern, myString)
    domains = {}
    for url in urls:
        parsed = urllib.parse.urlparse(url)
        domain = parsed.netloc
        if domain and domain not in domains:
            domains[domain] = None
    for domain in domains:
        try:
            response = requests.get(f'http://ip-api.com/json/{domain}?fields=status,message,country,regionName,city,zip,lat,lon,timezone,isp,org,as,query&key={API_KEY}')
            data = response.json()
            if data.get('status') == 'success':
                domains[domain] = data
            else:
                domains[domain] = None
        except:
            domains[domain] = None
    return domains

