import json
import os
def task_func(directory_path: str) -> dict:
    key_counts = collections.defaultdict(int)
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            with open(file_path, 'r') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    continue
                stack = [data]
                while stack:
                    current = stack.pop()
                    if isinstance(current, dict):
                        for key in current:
                            key_counts[key] += 1
                            stack.append(current[key])
                    elif isinstance(current, list):
                        stack.extend(current)
    return dict(key_counts)

import json
import os
import re
def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},
            "age": {"type": int},
            "email": {"type": str}
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):
    if not os.path.exists(file_path):
        raise ValueError("File does not exist.")
    with open(file_path, 'r') as f:
        data = json.load(f)
    required = INPUT_JSON.get("required", [])
    properties = INPUT_JSON.get("properties", {})
    for field in required:
        if field not in data:
            raise ValueError(f"Missing required attribute: {field}")
    for field, schema in properties.items():
        if field in data:
            expected_type = schema.get("type")
            if not isinstance(data[field], expected_type):
                raise ValueError(f"Type mismatch for {field}.")
    if "email" in data:
        if not re.match(EMAIL_REGEX, data["email"]):
            raise ValueError("Invalid email format.")
    return data[attribute]

