import re
from collections import Counter
REPLACE_NONE = "None"
EMAIL_PATTERN = r'\b[\w\.-]+@[\w\.-]+\.\w+\b'
def task_func(json_str):
    def process(item):
        if isinstance(item, dict):
            return {k: process(v) for k, v in item.items() if v is not None}
        elif isinstance(item, list):
            return [process(i) for i in item if i is not None]
        elif isinstance(item, str):
            return re.sub(EMAIL_PATTERN, REPLACE_NONE, item)
        else:
            return item

    data = json.loads(json_str)
    processed = process(data)

    def collect_values(obj, values):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, values)
        elif isinstance(obj, list):
            for i in obj:
                collect_values(i, values)
        else:
            values.append(obj)

    all_values = []
    collect_values(processed, all_values)
    value_counts = Counter(all_values)

    return {"data": processed, "value_counts": value_counts}

